import { ViewTransition } from 'react'

const navAnimations = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
} as const

export function PageTransition({ children }: { children: React.ReactNode }) {
  return (
    <ViewTransition
      enter={navAnimations}
      exit={navAnimations}
      default="none"
    >
      {children}
    </ViewTransition>
  )
}

